```php
<?php

function smart_sort_array($set, $order = 0) {
    // Sorts the array based on the age attribute of the associative sub-arrays
    usort($set, function($a, $b) use ($order) {
        return $a['age'] <=> $b['age'];
    });

    // Adjust the sorting order if needed
    switch ($order) {
        case 0:
            return $set;
            break;
        case -1:
            foreach ($set as &$item) {
                $item['age'] = -$item['age'];
            }
            return $set;
            break;
        default:
            return false;
            break;
    }
}

// Example usage:

