    ['name' => 'Alice', 'address' => '', 'age' => 30],
    ['name' => 'Bob', 'address' => '', 'age' => 25],
    ['name' => 'Charlie', 'address' => '', 'age' => 35]
];

// Default sorting: from youngest to oldest
$sortedPeopleDefault = smart_sort_array($people);
print_r($sortedPeopleDefault);

// Sorting from oldest to youngest
