				specs := n.Specs[0].(*ast.TypeSpec)
				if specs.Name.Name == "struct" {
					fieldDefs = append(fieldDefs, newFieldDefinition(specs))
				}
			}
		case *ast.Field:
			fieldDefs = append(fieldDefs, newFieldDefinition(node))
		}
	}

	structDef.Fields = fieldDefs
	return structDef, nil
}

// Create a new FieldDefinition based on the AST node representing a struct field.
